def balanced(s):
    count = 0
    for char in s:
        if char == '(':
            count += 1
        elif char == ')':
            count -= 1
        elif char in '[]{}':
            if count == 0:
                return False
            if char == '[':
                count -= 1
            elif char == '{':
                count -= 1
            elif char == '}':
                count += 1
            elif char == ']':
                count += 1
    return count == 0
