def camel_to_snake(s):
    def handle_word(w):
        if w.islower():
            return w
        parts = []
        for c in w:
            if c.isupper():
                parts.append('_')
                parts.append(c.lower())
            else:
                parts.append(c)
        return ''.join(parts)

    # Initialiser un produit avec le premier mot sans conversion
    words = [s]
    seen = {s}

    while words[-1] != '_':
        word = words[-1]
        next_word = handle_word(word)
        if next_word == word:
            # Si on a déjà rencontré cette phrase complète, la liste est vide
            if not words:
                break
            words.pop()
            seen.remove(word)
        else:
            # Sinon, ajouter la nouvelle version non convertie
            words.append(next_word)
            seen.add(word)
    return ''.join(words)

